class Solution {
public:
    vector<string> getWordsInLongestSubsequence(vector<string>& words, vector<int>& groups) {
        int n = words.size();
        vector<int> dp(n, 1), prev(n, -1);
        int best_idx = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (groups[i] != groups[j] && words[i].size() == words[j].size()) {
                    int diff = 0;
                    for (int k = 0; k < words[i].size(); k++) {
                        if (words[i][k] != words[j][k]) diff++;
                    }
                    if (diff == 1 && dp[j] + 1 > dp[i]) {
                        dp[i] = dp[j] + 1;
                        prev[i] = j;
                    }
                }
            }
            if (dp[i] > dp[best_idx]) best_idx = i;
        }
        vector<string> ans;
        for (int curr = best_idx; curr != -1; curr = prev[curr]) {
            ans.push_back(words[curr]);
        }
        reverse(ans.begin(), ans.end());
        return ans;
    }
};

class Solution {
    public List<String> getWordsInLongestSubsequence(String[] words, int[] groups) {
        int n = words.length;
        int[] dp = new int[n];
        int[] prev = new int[n];
        Arrays.fill(dp, 1);
        Arrays.fill(prev, -1);
        int bestIdx = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (groups[i] != groups[j] && words[i].length() == words[j].length()) {
                    int diff = 0;
                    for (int k = 0; k < words[i].length(); k++) {
                        if (words[i].charAt(k) != words[j].charAt(k)) diff++;
                    }
                    if (diff == 1 && dp[j] + 1 > dp[i]) {
                        dp[i] = dp[j] + 1;
                        prev[i] = j;
                    }
                }
            }
            if (dp[i] > dp[bestIdx]) bestIdx = i;
        }
        List<String> ans = new ArrayList<>();
        for (int curr = bestIdx; curr != -1; curr = prev[curr]) {
            ans.add(words[curr]);
        }
        Collections.reverse(ans);
        return ans;
    }
}

/**
 * @param {string[]} words
 * @param {number[]} groups
 * @return {string[]}
 */
var getWordsInLongestSubsequence = function(words, groups) {
    const n = words.length;
    const dp = new Int32Array(n).fill(1);
    const prev = new Int32Array(n).fill(-1);
    let bestIdx = 0;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (groups[i] !== groups[j] && words[i].length === words[j].length) {
                let diff = 0;
                for (let k = 0; k < words[i].length; k++) {
                    if (words[i][k] !== words[j][k]) diff++;
                }
                if (diff === 1 && dp[j] + 1 > dp[i]) {
                    dp[i] = dp[j] + 1;
                    prev[i] = j;
                }
            }
        }
        if (dp[i] > dp[bestIdx]) bestIdx = i;
    }
    const ans = [];
    for (let curr = bestIdx; curr !== -1; curr = prev[curr]) {
        ans.push(words[curr]);
    }
    ans.reverse();
    return ans;
};
